const request = $json;
const body = request.body;
const fail = (responseCode, error, message) => [{ json: { ok: false, responseCode, response: { error, message } } }];

if (typeof body !== 'object' || body === null || Array.isArray(body)) return fail(400, 'invalid_body', 'Le corps JSON doit etre un objet.');
if (JSON.stringify(body).length > 8192) return fail(400, 'body_too_large', 'Le corps JSON depasse 8 Ko.');

const headers = request.headers || {};
const clientIp = String(headers['x-forwarded-for'] || headers['x-real-ip'] || 'local').split(',')[0].trim();
const state = $getWorkflowStaticData('global');
state.rateLimits = state.rateLimits || {};
const now = Date.now();
const windowMs = 60000;
for (const [ip, bucket] of Object.entries(state.rateLimits)) if (now - bucket.startedAt >= windowMs) delete state.rateLimits[ip];
const bucket = state.rateLimits[clientIp] || { startedAt: now, count: 0 };
if (now - bucket.startedAt >= windowMs) { bucket.startedAt = now; bucket.count = 0; }
bucket.count += 1;
state.rateLimits[clientIp] = bucket;
if (bucket.count > 10) return fail(429, 'rate_limited', 'Limite de 10 signalements par minute depassee.');

const allowed = new Set(['type', 'value', 'context', 'reporterContact']);
const unexpected = Object.keys(body).filter((key) => !allowed.has(key));
if (unexpected.length) return fail(400, 'unexpected_fields', `Champs inattendus : ${unexpected.join(', ')}.`);
if (body.type !== 'url' && body.type !== 'wallet') return fail(400, 'invalid_type', `type doit etre exactement 'url' ou 'wallet'.`);
if (typeof body.value !== 'string' || !body.value || body.value.length > 2048) return fail(400, 'invalid_value', 'value doit etre une chaine non vide de 2048 caracteres maximum.');
if (body.context !== undefined && (typeof body.context !== 'string' || body.context.length > 1000)) return fail(400, 'invalid_context', 'context doit contenir 1000 caracteres maximum.');
if (body.reporterContact !== undefined && (typeof body.reporterContact !== 'string' || body.reporterContact.length > 200)) return fail(400, 'invalid_reporter_contact', 'reporterContact doit contenir 200 caracteres maximum.');

if (body.type === 'url') {
  if (!/^https?:\/\//i.test(body.value)) return fail(400, 'invalid_url', 'URL HTTP(S) invalide.');
  const authority = body.value.replace(/^https?:\/\//i, '').split(/[\/?#]/, 1)[0];
  if (!authority || authority.includes('@')) return fail(400, 'invalid_url', 'URL avec identifiants interdite ou domaine absent.');
} else if (!/^0x[a-fA-F0-9]{40}$/.test(body.value)) {
  return fail(400, 'invalid_wallet', 'Adresse EVM invalide.');
}

return [{ json: { ok: true, type: body.type, value: body.value, context: body.context || null, reporterContact: body.reporterContact || null } }];

const source = $('Valider et limiter').first().json;
const createdAt = new Date().toISOString();
const stamp = createdAt.replace(/[-:]/g, '').replace(/\.\d{3}/, '');
const executionPart = String($execution.id || Date.now()).replace(/[^A-Za-z0-9_-]/g, '').slice(0, 64);
const reportId = `r_${stamp}_${executionPart}`;
const valueDefanged = source.type === 'url' ? source.value.replace(/^http/i, 'hxxp').replace(/\./g, '[.]') : source.value;
return [{ json: { reportId, createdAt, type: source.type, valueDefanged, status: 'queued' } }];
